contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount1, uint amount2, address other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(amount1 > 0 && amount2 > 0);
        require(amount1 + amount2 >= amount1 && amount1 + amount2 >= amount2);
        require(address(this).balance >= amount1 + amount2);
        uint beforeBal = address(c).balance;
        c.addToBalance{value: amount1}(); if (__ESBMC_reverted()) return;
        uint midBal = address(c).balance;
        c.addToBalance{value: amount2}(); if (__ESBMC_reverted()) return;
        uint finalBal = address(c).balance;
        assert(midBal == beforeBal + amount1 && finalBal == midBal + amount2 && c.getBalance(other) == 0);
    }
    receive() external payable {}
}

